/* CSS 기본 문법 */
선택자 {
  속성: 값;
}

/* 예시 */
h1 {
  color: var(--accent);
  font-size: 2rem;
  font-weight: 900;
}

/* 태그 선택자 */
p { color: var(--ink-1); }

/* 클래스 선택자 */
.card { background: white; border-radius: 12px; }

/* ID 선택자 */
#header { height: 64px; }

/* 자식 선택자 */
.nav > a { font-weight: 600; }

/* 가상 클래스 */
button:hover { background: var(--accent-h); }

.box {
  /* 콘텐츠 크기 */
  width: 200px;
  height: 100px;

  /* 안쪽 여백 */
  padding: 16px 24px;

  /* 테두리 */
  border: 2px solid var(--accent);
  border-radius: 12px;

  /* 바깥 여백 */
  margin: 20px auto;

  /* 박스 크기 계산 방식 */
  box-sizing: border-box;
}

.container {
  display: flex;
  justify-content: space-between; /* 가로 정렬 */
  align-items: center;           /* 세로 정렬 */
  gap: 16px;                     /* 간격 */
  flex-wrap: wrap;               /* 줄바꿈 허용 */
}

.item {
  flex: 1;      /* 남은 공간 균등 분배 */
  min-width: 200px;
}

.cards-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: 24px;
}

/* 특정 영역 병합 */
.featured {
  grid-column: span 2;
  grid-row: span 2;
}

/* 모바일 기본 */
.grid { grid-template-columns: 1fr; }

/* 태블릿 */
@media (min-width: 768px) {
  .grid { grid-template-columns: 1fr 1fr; }
}

/* 데스크탑 */
@media (min-width: 1024px) {
  .grid { grid-template-columns: repeat(3, 1fr); }
}

// 첫 번째 JavaScript 코드
console.log("Hello, JavaScript!");

// 브라우저 알림
alert("안녕하세요!");

// HTML 요소 변경
document.title = "새로운 제목";

// 변수 선언
